const fs=require('node:fs'),path=require('node:path');const sharp=require(process.env.GPT_ART_SHARP_MODULE||'sharp');
const dir=path.join(__dirname,'delivery-20261116');const rows=require('./delivery-20261116/measurements.json');
(async()=>{const tiles=[];for(const r of rows){const image=fs.readFileSync(path.join(dir,'64px',r.id+'.png'));const m=await sharp(image).metadata();for(const bg of ['#f5f6f4','#202927'])tiles.push(await sharp({create:{width:100,height:100,channels:3,background:bg}}).composite([{input:image,left:Math.floor((100-m.width)/2),top:Math.floor((100-m.height)/2)}]).png().toBuffer())}await sharp({create:{width:400,height:500,channels:3,background:'#d5dad5'}}).composite(tiles.map((input,i)=>({input,left:i%4*100,top:Math.floor(i/4)*100}))).png().toFile(path.join(dir,'64px-contact-sheet.png'));fs.writeFileSync(path.join(dir,'preview.html'),`<!doctype html><html lang="zh-CN"><meta charset="UTF-8"><title>墨境 · 美术交付检查</title><style>body{background:#f5f6f4;color:#202927;font:15px sans-serif;margin:24px}button{padding:8px 18px}main{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:18px;margin-top:20px}article{border:1px solid #85908a;padding:15px}img{display:block;max-width:100%;height:260px;object-fit:contain;margin:auto}.dark{background:#202927;color:#f5f6f4}small{display:block;margin:10px}a{color:inherit}</style><h1>墨境 · 10张美术交付检查</h1><button onclick="document.body.classList.toggle('dark')">切换深浅底</button><p>点击查看原尺寸；下方缩略图为64px。顺序：六灵宠、男女素衣、男女套装。</p><main>${rows.map(r=>`<article><b>${r.id}</b><a href="../../../${r.path}"><img src="../../../${r.path}" alt="${r.id}"></a><small>${r.width}×${r.height} · ${r.bytes} bytes</small><img src="64px/${r.id}.png" style="width:auto;height:auto;max-width:64px;max-height:64px" alt="64px ${r.id}"></article>`).join('')}</main></html>`);console.log('Preview generated')})().catch(e=>{console.error(e);process.exitCode=1});
